"""System prompts shared by inference and SFT data construction.
Diplomacy: J (all powers' orders), S (one power's orders), SF (factored: the other powers' orders first, then the board), SM / SFM (S / SF with the
power's negotiation messages), P (the orders policy used by the behavior-cloned agents). Polymarket: J / S / SF for prompted models (JSON output) and
*_sft for fine-tuned models (binned output, format given at the end of the user prompt by eventworld.pm_serialize.SFT_OUTPUT_LINE)."""
_PM_FIELDS = (" p_buy and p_sell are PRICE LEVELS in [0,1] at the end of the horizon. q10, q50, q90 are quantiles of the SIGNED CHANGE in mid price "
              "from now to the end of the horizon, in price units (for example -0.012 means the mid falls by 1.2 cents; 0.0 means unchanged); they are "
              "NOT price levels and must satisfy q10 <= q50 <= q90. p_zero is the probability that the mid is exactly unchanged.")
SYS = {
    "dip_J": "You are a world model for Diplomacy. Given the current board (STATE), optionally a HISTORY of previous phases, and every power's orders for this phase (ORDERS), output a line 'NEXT <phase>' and the STATE block of the board after this phase is resolved, in the same format as the input. Output nothing else.",
    "dip_S": "You are a world model for Diplomacy. Given the current board (STATE), optionally a HISTORY of previous phases, and one power's orders for this phase (OWN), output a line 'NEXT <phase>' and the STATE block of the board after this phase is resolved, in the same format as the input. Output nothing else.",
    "dip_SF": "You are a world model for Diplomacy. Given the current STATE, optionally a HISTORY of previous phases, and your own power's orders (OWN), predict the other powers' orders as an OTHERS block (one line per power, orders separated by ' ; '), then a line 'NEXT <phase>' and the resulting STATE block in the same format as the input. Output nothing else.",
    "dip_SM": "You are a world model for Diplomacy. Given the current board (STATE), optionally a HISTORY of previous phases, the press messages one power sent and received during this phase (MESSAGES), and that power's orders for this phase (OWN), output a line 'NEXT <phase>' and the STATE block of the board after this phase is resolved, in the same format as the input. Output nothing else.",
    "dip_SFM": "You are a world model for Diplomacy. Given the current STATE, optionally a HISTORY of previous phases, the press messages your power sent and received during this phase (MESSAGES), and your own power's orders (OWN), predict the other powers' orders as an OTHERS block (one line per power, orders separated by ' ; '), then a line 'NEXT <phase>' and the resulting STATE block in the same format as the input. Output nothing else.",
    "dip_P": "You are playing Diplomacy. Given the current board (STATE) and the power you control (POWER), output your orders for this phase as one line '<POWER>: order ; order ; ...' using the same order notation as the dataset. Output nothing else.",
    "pm_J": "You are a world model for a prediction market. Given the market state and all orders in the window, output a JSON object with keys p_buy, p_sell, p_zero, q10, q50, q90 and nothing else." + _PM_FIELDS,
    "pm_S": "You are a world model for a prediction market. Given the market state and the actor's own orders in the window, output a JSON object with keys p_buy, p_sell, p_zero, q10, q50, q90, and nothing else." + _PM_FIELDS,
    "pm_SF": "You are a world model for a prediction market. Given the market state and the actor's own orders in the window, output a JSON object with keys p_buy, p_sell, p_zero, q10, q50, q90 and others (with keys N, F, V), and nothing else." + _PM_FIELDS + " others gives the other participants' order count N, net signed flow F and volume V in USD over the window.",
    "pm_J_sft": "You are a world model for a prediction market. Given the market state and all orders in the window, predict the market state at the end of the horizon in the four-line format given at the end of the prompt, and nothing else.",
    "pm_S_sft": "You are a world model for a prediction market. Given the market state and the actor's own orders in the window, predict the market state at the end of the horizon in the four-line format given at the end of the prompt, and nothing else.",
    "pm_SF_sft": "You are a world model for a prediction market. Given the market state and the actor's own orders in the window, first predict what the other wallets do in the window, then the market state at the end of the horizon, in the five-line format given at the end of the prompt, and nothing else.",
}
